"use client";

import { useState } from "react";
import { useForm, SubmitHandler } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { ImportPreview } from "./import-preview";
import { ValidationResult } from "@/schemas/backup";
import { Loader2, Upload } from "lucide-react";

function isFileListLike(value: unknown): boolean {
  if (typeof window === "undefined") return true;
  if (value === null || value === undefined) return false;
  if (typeof value !== "object") return false;
  const length = (value as { length?: unknown }).length;
  return typeof length === "number" && length > 0;
}

const formSchema = z.object({
  file: z.any().refine((files) => isFileListLike(files), "A file is required."),
});

type FormValues = z.infer<typeof formSchema>;

async function validateBackup(file: File): Promise<ValidationResult> {
  const formData = new FormData();
  formData.append("file", file);

  const response = await fetch("/api/admin/backup/validate", {
    method: "POST",
    body: formData,
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(errorData.message || "Failed to validate backup file.");
  }

  return response.json();
}

export function BackupImport() {
  const { toast } = useToast();
  const [validationResult, setValidationResult] =
    useState<ValidationResult | null>(null);
  const [backupFile, setBackupFile] = useState<File | null>(null);

  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm<FormValues>({
    resolver: zodResolver(formSchema),
  });

  const mutation = useMutation({
    mutationFn: (file: File) => validateBackup(file),
    onSuccess: (data) => {
      setValidationResult(data);
      toast({
        title: "Validation Successful",
        description: "Review the import preview below.",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Validation Failed",
        description: error.message,
        variant: "destructive",
      });
      reset();
    },
  });

  const onSubmit: SubmitHandler<FormValues> = (data) => {
    const file = data.file[0];
    if (file) {
      setBackupFile(file);
      mutation.mutate(file);
    }
  };

  const handleReset = () => {
    setValidationResult(null);
    setBackupFile(null);
    reset();
  };

  if (validationResult && backupFile) {
    return (
      <ImportPreview
        result={validationResult}
        file={backupFile}
        onReset={handleReset}
      />
    );
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
      <div className="space-y-2">
        <Label htmlFor="backup-file">Backup File (.zip)</Label>
        <Input
          id="backup-file"
          type="file"
          accept=".zip"
          {...register("file")}
        />
        {errors.file?.message && (
          <p className="text-sm text-destructive">
            {String(errors.file.message)}
          </p>
        )}
      </div>
      <p className="text-sm text-muted-foreground">
        Importing will add or update data. It is strongly recommended to perform
        a backup first.
      </p>
      <Button type="submit" disabled={mutation.isPending}>
        {mutation.isPending ? (
          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
        ) : (
          <Upload className="mr-2 h-4 w-4" />
        )}
        {mutation.isPending ? "Validating..." : "Validate Backup"}
      </Button>
    </form>
  );
}

import { requireAdmin } from "@/lib/auth";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { BackupExport } from "@/components/admin/backup-export";
import { BackupImport } from "@/components/admin/backup-import";

export default async function BackupAdminPage() {
  await requireAdmin();

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold">Backup & Restore</h1>
      <p className="text-muted-foreground">
        Export your family tree data or import it from a backup file.
      </p>
      <div className="grid gap-6 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle>Export Data</CardTitle>
          </CardHeader>
          <CardContent>
            <BackupExport />
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Import Data</CardTitle>
          </CardHeader>
          <CardContent>
            <BackupImport />
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { useRouter } from "next/navigation";
import { ValidationResult, ConflictResolutionStrategy } from "@/schemas/backup";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useToast } from "@/hooks/use-toast";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { AlertTriangle, CheckCircle, Loader2 } from "lucide-react";

interface ImportPreviewProps {
  result: ValidationResult;
  file: File;
  onReset: () => void;
}

async function importBackup({
  file,
  strategy,
}: {
  file: File;
  strategy: ConflictResolutionStrategy;
}) {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("strategy", strategy);

  const response = await fetch("/api/admin/backup/import", {
    method: "POST",
    body: formData,
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(errorData.message || "Failed to import backup.");
  }

  return response.json();
}

export function ImportPreview({ result, file, onReset }: ImportPreviewProps) {
  const { toast } = useToast();
  const router = useRouter();
  const [strategy, setStrategy] = useState<ConflictResolutionStrategy>("skip");
  const [isImporting, setIsImporting] = useState(false);

  const mutation = useMutation({
    mutationFn: importBackup,
    onSuccess: () => {
      toast({
        title: "Import Successful",
        description: "Your data has been imported.",
      });
      router.refresh();
      onReset();
    },
    onError: (error: Error) => {
      toast({
        title: "Import Failed",
        description: error.message,
        variant: "destructive",
      });
    },
    onSettled: () => {
      setIsImporting(false);
    },
  });

  const handleImport = () => {
    setIsImporting(true);
    mutation.mutate({ file, strategy });
  };

  const personConflicts = result.conflicts.filter((c) => c.type === "person");
  const relationshipConflicts = result.conflicts.filter(
    (c) => c.type === "relationship"
  );
  const hasConflicts =
    personConflicts.length > 0 || relationshipConflicts.length > 0;

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Import Preview</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <p>
            Validation successful. Review the data to be imported from{" "}
            <span className="font-semibold">{file.name}</span>.
          </p>
          <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
            <div className="rounded-lg border p-4">
              <div className="text-sm text-muted-foreground">People</div>
              <div className="text-2xl font-bold">
                {result.metadata.statistics.totalPeople}
              </div>
            </div>
            <div className="rounded-lg border p-4">
              <div className="text-sm text-muted-foreground">Relationships</div>
              <div className="text-2xl font-bold">
                {result.metadata.statistics.totalRelationships}
              </div>
            </div>
            <div className="rounded-lg border p-4">
              <div className="text-sm text-muted-foreground">Conflicts</div>
              <div className="text-2xl font-bold">
                {result.statistics.totalConflicts}
              </div>
            </div>
            <div className="rounded-lg border p-4">
              <div className="text-sm text-muted-foreground">Users</div>
              <div className="text-2xl font-bold">
                {result.metadata.statistics.totalUsers}
              </div>
            </div>
          </div>
